/usr/bin/bash -lc "perl -e '
use strict; use warnings;
my (%cand,%verified,%protmap);
open my "'$cf,"<","data/inputs/distinct_peptides_for_pepquery/Distinct_Peptides_for_PepQuery.tabular" or die $!;
while(<$cf>){chomp; s/'"\\r"'$//; next unless /'"\\S/; "'$cand{uc $_}=1} close $cf;
for my $f (glob("run_trace/galaxy_outputs/*_psm_rank.tsv")){
  open my $fh,"<",$f or die $!;
  my $h=<$fh>; chomp $h; $h =~ s/'"\\r"'$//; my @h=split /'"\\t/,"'$h,-1; my %i; @i{@h}=0..$#h;
  die "missing columns in $f'"\\n\" unless exists "'$i{peptide} && exists $i{confident};
  while(<$fh>){chomp; s/'"\\r"'$//; my @f=split /'"\\t/,"'$_,-1; my $pep=uc($f[$i{peptide}]//""); next unless $cand{$pep}; $verified{$pep}=1 if ($f[$i{confident}]//"") eq "Yes";}
  close $fh;
}
sub add_prots {
  my ($path,$protcol)=@_;
  open my $fh,"<",$path or die $!;
  my $h=<$fh>; chomp $h; $h =~ s/'"\\r"'$//; my @h=split /'"\\t/,"'$h,-1; my %i; @i{@h}=0..$#h;
  die "missing Sequence in $path'"\\n\" unless exists "'$i{Sequence}; die "missing $protcol in $path'"\\n\" unless exists "'$i{$protcol};
  while(<$fh>){chomp; s/'"\\r"'$//; my @f=split /'"\\t/,"'$_,-1; my $pep=uc($f[$i{Sequence}]//""); next unless $verified{$pep}; my $s=$f[$i{$protcol}]//""; next unless length $s;
    for my $tok (split /[;]+/, $s){ $tok =~ s/''^'"\\s+|\\s+"'$//g; next unless length $tok; $protmap{$pep}{$tok}=1; }
  }
  close $fh;
}
add_prots("data/inputs/sgps_peptide_report/SGPS_peptide-report.tabular","Protein(s)");
add_prots("data/inputs/maxquant_peptide_report/MaxQuant-peptide-report.tabular","Proteins");
