/usr/bin/bash -lc "perl -e '
use strict; use warnings;
my (%cand,%verified,%protmap);
open my "'$cf,"<","data/inputs/distinct_peptides_for_pepquery/Distinct_Peptides_for_PepQuery.tabular" or die $!;
while(<$cf>){chomp; s/'"\\r"'$//; next unless /'"\\S/; "'$cand{uc $_}=1} close $cf;
for my $rank (glob("run_trace/galaxy_outputs/*_psm_rank.tsv")){
  open my $fh,"<",$rank or die $!;
  my $h=<$fh>; chomp $h; $h =~ s/'"\\r"'$//; my @h=split /'"\\t/,"'$h,-1; my %i; @i{@h}=0..$#h;
  die "missing peptide/confident columns in $rank'"\\n\" unless exists "'$i{peptide} && exists $i{confident};
  while(<$fh>){chomp; s/'"\\r"'$//; my @f=split /'"\\t/,"'$_,-1; my $pep=uc($f[$i{peptide}]//""); next unless $cand{$pep}; $verified{$pep}=1 if ($f[$i{confident}]//"") eq "Yes";}
  close $fh;
}
sub normalize_id {
  my ($tok)=@_;
  $tok =~ s/''^'"\\s+|\\s+"'$//g;
  return () unless length $tok;
  my @out;
  for my $part (split /,/, $tok) {
    $part =~ s/''^'"\\s+|\\s+"'$//g;
    next unless length $part;
    if ($part =~ /''^[a-z]{2}'"\\|(["'^|]+)'"\\|/i) { push @out, "'$1; }
    else { push @out, $part; }
  }
  return @out;
}
sub add_report {
  my ($path,$protcol)=@_;
  open my $fh,"<",$path or die $!;
  my $h=<$fh>; chomp $h; $h =~ s/'"\\r"'$//; my @h=split /'"\\t/,"'$h,-1; my %i; @i{@h}=0..$#h;
  die "missing Sequence or $protcol in $path'"\\n\" unless exists "'$i{Sequence} && exists $i{$protcol};
  while(<$fh>){
    chomp; s/'"\\r"'$//; my @f=split /'"\\t/,"'$_,-1; my $pep=uc($f[$i{Sequence}]//""); next unless $verified{$pep};
    for my $tok (split /;/, ($f[$i{$protcol}]//"")) { for my $pid (normalize_id($tok)) { $protmap{$pep}{$pid}=1; } }
  }
  close $fh;
}
add_report("data/inputs/sgps_peptide_report/SGPS_peptide-report.tabular","Protein(s)");
add_report("data/inputs/maxquant_peptide_report/MaxQuant-peptide-report.tabular","Proteins");
mkdir "final_answer" unless -d "final_answer";
open my $out,">","final_answer/verified_peptides.tsv" or die $!;
print $out "peptide'"\\tprotein_id\\n\";
for my "'$pep (sort keys %protmap) { for my $pid (sort keys %{$protmap{$pep}}) { print $out "$pep'"\\t"'$pid'"\\n\"; } }
close "'$out;
open my $log,">","run_trace/execution_log.tsv" or die $!;
print $log "key'"\\tvalue\\n\";
print "'$log "assigned_history'"\\tbbd44e69cb8906b5fe12c068e9426588\\n\";
print "'$log "pepquery2_tool'"\\ttoolshed.g2.bx.psu.edu/repos/galaxyp/pepquery2/pepquery2/2.0.2+galaxy2\\n\";
print "'$log "candidate_peptides'"\\t\".scalar(keys %cand).\"\\n\";
print "'$log "verified_peptides_confident_yes'"\\t\".scalar(keys %verified).\"\\n\";
my "'$pairs=0; $pairs += scalar(keys %{$protmap{$_}}) for keys %protmap;
print $log "peptides_with_report_assignments'"\\t\".scalar(keys %protmap).\"\\n\";
print "'$log "final_pairs'"\\t"'$pairs'"\\n\";
print "'$log "job_ids'"\\t\".join(\",\", qw(bbd44e69cb8906b55b6203afea02869e bbd44e69cb8906b53431ee47a669d29a bbd44e69cb8906b56bfc3eba5374565c bbd44e69cb8906b53fbec0bb31042050)).\"\\n\";
close "'$log;
'"' 
wc -l final_answer/verified_peptides.tsv
sed -n '1,20p' final_answer/verified_peptides.tsv
sed -n '1,20p' run_trace/execution_log.tsv"

